mapper.select:
SELECT i.id, i.inspect_no, i.inspect_type, i.source_type, i.source_id, i.source_no, i.template_id, t.template_name, i.material_id, m.code AS material_code, m.name AS material_name, m.spec, u.name AS unit, i.supplier_id, s.name AS supplier_name, i.sample_qty, i.qualified_qty, i.unqualified_qty, i.conclusion, i.inspector_name, i.inspect_date, i.status, i.submit_time, i.remark, i.create_time FROM qc_inspect i LEFT JOIN qc_template t ON t.id = i.template_id AND t.deleted = 0 LEFT JOIN base_material m ON m.id = i.material_id AND m.deleted = 0 LEFT JOIN base_unit u ON u.id = m.unit_id AND u.deleted = 0 LEFT JOIN base_supplier s ON s.id = i.supplier_id AND s.deleted = 0
i.deleted = 0
AND (i.inspect_no LIKE CONCAT('%', #{q.keyword}, '%') OR i.source_no LIKE CONCAT('%', #{q.keyword}, '%'))
AND i.inspect_type = #{q.inspectType} AND i.source_type = #{q.sourceType} AND i.material_id = #{q.materialId} AND i.conclusion = #{q.conclusion} AND i.status = #{q.status}
AND i.inspect_date >= #{q.dateBegin} AND i.inspect_date <= #{q.dateEnd}
ORDER BY i.id DESC
